    chargeSfx: 'super_void_charge', finishSfx: 'super_void',
    cd: 9, chargeDur: 2.1, blastR: 210, power: 5,
    hint: 'Lv 30', tooltip: 'Donkere puls trekt alles naar binnen en explodeert.',
