function seedNlFromRuntime() {
  if (typeof ACHIEVEMENTS !== 'undefined') {
    if (!I18N.nl.ach) I18N.nl.ach = {};
    for (const a of ACHIEVEMENTS) I18N.nl.ach[a.id] = { name: a.name, desc: a.desc };
  }
  if (typeof DAILY_DEFS !== 'undefined') {
    if (!I18N.nl.daily) I18N.nl.daily = {};
    for (const d of DAILY_DEFS) {
      if (!I18N.nl.daily[d.id]) I18N.nl.daily[d.id] = {};
      I18N.nl.daily[d.id].text = d.text;
    }
  }
  if (typeof DAILY_PLAY_HINTS !== 'undefined') {
    if (!I18N.nl.daily) I18N.nl.daily = {};
    for (const id of Object.keys(DAILY_PLAY_HINTS)) {
      if (!I18N.nl.daily[id]) I18N.nl.daily[id] = {};
      I18N.nl.daily[id].hint = DAILY_PLAY_HINTS[id];
    }
  }
  if (typeof WEAPONS !== 'undefined') {
    if (!I18N.nl.weapon) I18N.nl.weapon = {};
    for (const w of WEAPONS) I18N.nl.weapon[w.id] = { name: w.name, desc: w.desc };
  }
  if (typeof STYLES !== 'undefined') {
    if (!I18N.nl.style) I18N.nl.style = {};
    for (const s of STYLES) I18N.nl.style[s.id] = { name: s.name, hint: s.hint, tooltip: s.tooltip, bonus: s.bonus };
  }
  if (typeof SKILLS !== 'undefined') {
    if (!I18N.nl.skill) I18N.nl.skill = {};
    for (const s of SKILLS) I18N.nl.skill[s.id] = { name: s.name, hint: s.hint, tooltip: s.tooltip, bonus: s.bonus };
    Object.assign(I18N.nl.skill, {
      behavior: { orb: 'Orb', dash: 'Dash', beam: 'Beam', disc: 'Disc', pull: 'Pull', meteor: 'Meteor', slash: 'Slash' },
      stat: { dmg: 'Schade', wind: 'Windup', spd: 'Snelheid', kb: 'Knockback' },
      tag: { pierce: 'Pierce', pull: 'Pull' },
      saga: {
        scroll: { blurb: 'Ninja-scroll — Spiral Orb, Lightning Pierce, Void Gaze-lichtschits & gravity specials.' },
        ki: { blurb: 'Ki-golven — Wave Cannon, discs, Energy Sphere & blitz dashes.' },
        tide: { blurb: 'Tide-straal — Moon Slash, Void Beam & Blade Ascend flash.' },
        fighter: { blurb: 'Street stretch — Stretch dash & Steam Burst steam.' },
        cape: { blurb: 'Hero specials — Thunder Palm & Heavy Series.' },
        dawn: { blurb: 'Dawn palm — solar orbs & lunar pull control.' },
      },
    });
  }
  if (typeof SUPERS !== 'undefined') {
    if (!I18N.nl.super) I18N.nl.super = {};
    for (const s of SUPERS) {
      I18N.nl.super[s.id] = {
        name: s.name, hint: s.hint, tooltip: s.tooltip, bonus: s.bonus,
        charge: s.chargeBanner, finish: s.finishBanner,
      };
    }
    Object.assign(I18N.nl.super, {
      behavior: {
        blast: 'Blast', shield: 'Schild', heal: 'Heal', mind_eye: 'Illusion',
        lightning: 'Bliksem', meteor: 'Meteor', rage: 'Rage', timestop: 'Tijd',
        clones: 'Clones', void: 'Void',
      },
      stat: { pow: 'Kracht', rad: 'Radius', cd: 'Cooldown', charge: 'Laden' },
      tag: {
        blast: 'Blast', knockback: 'Knockback', defense: 'Verdediging', push: 'Push',
        heal: 'Heal', illusion: 'Illusion', pull: 'Pull', slow: 'Slow',
        lightning: 'Bliksem', 'multi-hit': 'Multi-hit', meteor: 'Meteor', zone: 'Zone',
        buff: 'Buff', freeze: 'Freeze', burst: 'Burst', rush: 'Rush', void: 'Void',
      },
    });
  }
  if (typeof PICKUP_META !== 'undefined') {
    if (!I18N.nl.pickup) I18N.nl.pickup = {};
    for (const kind of PICKUP_TYPES || Object.keys(PICKUP_META)) {
      const m = PICKUP_META[kind];
      if (m && m.label) I18N.nl.pickup[kind] = m.label;
    }
  }
}

function mergeI18nCatalogs() {
  seedNlFromRuntime();
  seedNlGameStrings();
  deepMergeI18n(I18N.en, CATALOG_EN);
  deepMergeI18n(I18N.de, CATALOG_DE);
  deepMergeI18n(I18N.fr, CATALOG_FR);
  deepMergeI18n(I18N.es, CATALOG_ES);
}

